WITH filtered AS (SELECT id, carrier, shipped_date, delivered_date, cost, CEIL(cost) AS cost_whole FROM shipments WHERE order_id IS NOT NULL) SELECT id, carrier, shipped_date, delivered_date, cost, cost_whole, NTILE(5) OVER (PARTITION BY carrier ORDER BY cost_whole ASC, id ASC) AS cost_whole_bucket, LAST_VALUE(cost_whole) IGNORE NULLS OVER (ORDER BY cost_whole ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost_whole FROM filtered
